  'Desbloqueado': 'Ξεμπλοκαρίστηκε',
  'Desbloquear': 'Ξεμπλοκάρισμα',
  'Descartar': 'Απόρριψη',
  'Desconecta o Syden em todos os outros computadores e celulares. Você continua conectado aqui.': 'Αποσυνδέει το Syden σε όλους τους άλλους υπολογιστές και στα κινητά. Εδώ παραμένεις συνδεδεμένος.',
  'Desconectando…': 'Αποσυνδέεται…',
  'Desconectar': 'Αποσύνδεση',
  'Descrição': 'Περιγραφή',
  'Desligado, a transmissão de quem está na sala aparece como convite e só começa a ser baixada quando você clica em Assistir. Isso poupa internet e processador — principalmente em sala cheia.': 'Κλειστό, η μετάδοση όποιου είναι στο δωμάτιο εμφανίζεται ως πρόσκληση και αρχίζει να κατεβαίνει μόνο όταν πατήσεις Παρακολούθηση. Έτσι γλιτώνεις ίντερνετ και επεξεργαστή — κυρίως σε γεμάτο δωμάτιο.',
  'Desligar câmera': 'Κλείσιμο κάμερας',
  'Deste servidor': 'Από αυτόν τον διακομιστή',
  'Diga o e-mail da sua conta e mandamos um link para escolher outra.': 'Πες το email του λογαριασμού σου και στέλνουμε σύνδεσμο για να διαλέξεις άλλον.',
  'Digite sua senha para confirmar': 'Γράψε τον κωδικό σου για επιβεβαίωση',
  'Disponível': 'Διαθέσιμος',
  'Do laranja ao vermelho, como carvão aceso.': 'Από το πορτοκαλί στο κόκκινο, σαν αναμμένο κάρβουνο.',
  'Dois emojis com o mesmo nome: cada um precisa do seu.': 'Δύο emoji με το ίδιο όνομα: το καθένα χρειάζεται το δικό του.',
  'Dono': 'Ιδιοκτήτης',
  'Dono da comunidade': 'Ιδιοκτήτης της κοινότητας',
  'Dourado com brilho que passa devagar.': 'Χρυσό με λάμψη που περνάει αργά.',
  'Durante uma chamada, esse botão toca estes sons para todos na sala. Instale pacotes prontos ou envie os seus; o que é seu favorito fica na frente do painel.': 'Σε μια κλήση, αυτό το κουμπί παίζει αυτούς τους ήχους για όλους στο δωμάτιο. Εγκατέστησε έτοιμα πακέτα ή ανέβασε δικούς σου· ό,τι είναι αγαπημένο σου μπαίνει μπροστά στον πίνακα.',
  'É a primeira coisa que alguém vê ao entrar na comunidade, uma vez só. Sem isto, a pessoa cai direto na lista de canais.': 'Είναι το πρώτο που βλέπει κανείς μπαίνοντας στην κοινότητα, μία μόνο φορά. Χωρίς αυτό, πέφτει κατευθείαν στη λίστα των καναλιών.',
  'É assim que os outros veem você na lista e nas conversas.': 'Έτσι σε βλέπουν οι άλλοι στη λίστα και στις συνομιλίες.',
  'é o que você está enviando': 'είναι αυτό που στέλνεις',
  'É o seu único jeito de entrar. Defina uma senha antes de desligar.': 'Είναι ο μόνος τρόπος σου να μπαίνεις. Όρισε κωδικό πριν το κλείσεις.',
