  'Endereço guardado. Confira a sua caixa de entrada para confirmar.': 'Η διεύθυνση αποθηκεύτηκε. Δες τα εισερχόμενά σου για να την επιβεβαιώσεις.',
  'Endereço guardado. O envio de e-mail ainda não está ligado neste servidor, então o link de confirmação ficou no registro do servidor.': 'Η διεύθυνση αποθηκεύτηκε. Η αποστολή email δεν είναι ακόμη ενεργή σε αυτόν τον διακομιστή, οπότε ο σύνδεσμος επιβεβαίωσης έμεινε στο αρχείο καταγραφής.',
