  'Escolha aqui a língua do Syden. Vale na hora, só para você, e fica guardada neste computador.': 'Διάλεξε εδώ τη γλώσσα του Syden. Ισχύει αμέσως, μόνο για σένα, και μένει αποθηκευμένη σε αυτόν τον υπολογιστή.',
