  'Canal de destaques': 'Κανάλι επιλεγμένων',
  'Destaques': 'Επιλεγμένα',
  'Estrelas necessárias': 'Αστέρια που χρειάζονται',
  'Quando uma mensagem junta estrelas ⭐ suficientes, o Syden a publica no canal de destaques. A estrela de quem escreveu não conta, e apagar a mensagem apaga o destaque.': 'Όταν ένα μήνυμα μαζέψει αρκετά αστέρια ⭐, το Syden το δημοσιεύει στο κανάλι επιλεγμένων. Το αστέρι από τον συντάκτη δεν μετράει, και η διαγραφή του μηνύματος διαγράφει και το επιλεγμένο.',
  '🎉 Resultado do sorteio de {premio}: {vencedores}. Parabéns!': '🎉 Αποτέλεσμα της κλήρωσης για {premio}: {vencedores}. Συγχαρητήρια!',
  '🎉 Sorteio: {premio}! Reaja com 🎉 para participar. O resultado sai em {quando}.': '🎉 Κλήρωση: {premio}! Αντέδρασε με 🎉 για να συμμετέχεις. Το αποτέλεσμα βγαίνει {quando}.',
  'Começar o sorteio': 'Έναρξη κλήρωσης',
  'Encerrar agora': 'Λήξη τώρα',
  'Ganhadores': 'Αριθμός δώρων',
  'Ninguém participou.': 'Δεν υπήρξε συμμετοχή.',
  'Novo sorteio': 'Νέα κλήρωση',
  'O sorteio de {premio} terminou sem participantes.': 'Η κλήρωση για {premio} έληξε χωρίς συμμετοχές.',
  'O Syden anuncia o prêmio no canal, e quem quiser participar reage com 🎉. Na hora marcada, ele sorteia entre quem reagiu e publica o resultado.': 'Το Syden ανακοινώνει το δώρο στο κανάλι, και όποιος θέλει να συμμετάσχει αντιδρά με 🎉. Την ώρα που ορίστηκε, κληρώνει ανάμεσα σε όσους αντέδρασαν και δημοσιεύει το αποτέλεσμα.',
  'Participantes: {n}': 'Συμμετοχές: {n}',
  'Prêmio': 'Δώρο',
