  'Aniversário': 'Γενέθλια',
  'Aniversários': 'Γενέθλια',
  'Canal dos parabéns': 'Κανάλι ευχών',
  'Dia': 'Ημέρα',
  'Hoje é aniversário de {pessoa}! 🎉 Parabéns!': 'Σήμερα έχει γενέθλια ο/η {pessoa}! 🎉 Χρόνια πολλά!',
  'Mês': 'Μήνας',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'Στα γενέθλια όποιου έχει δώσει την ημερομηνία, το Syden δημοσιεύει ευχές στο κανάλι που διάλεξες. Χρησιμοποίησε το {pessoa} στη θέση του ονόματος.',
  'Só o dia e o mês, nunca o ano. As comunidades que avisam aniversários dão os parabéns no dia. É opcional, e dá para apagar quando quiser.': 'Μόνο η μέρα και ο μήνας, ποτέ η χρονιά. Οι κοινότητες που ανακοινώνουν γενέθλια στέλνουν ευχές την ίδια μέρα. Είναι προαιρετικό και διαγράφεται όποτε θέλεις.',
  'Texto dos parabéns': 'Κείμενο ευχών',
