  'Mensagens agendadas': 'Προγραμματισμένα μηνύματα',
  'Na hora marcada, o Syden publica o texto no canal. Dá para repetir todo dia ou toda semana.': 'Την ώρα που ορίζεις, το Syden δημοσιεύει το κείμενο στο κανάλι. Μπορεί να επαναλαμβάνεται κάθε μέρα ή κάθε εβδομάδα.',
  'Nova mensagem agendada': 'Νέο προγραμματισμένο μήνυμα',
