  'Uma vez': 'Μία φορά',
  'Alguém escreve o comando no começo de uma mensagem, como !regras, e o Syden responde no canal com o texto que você cadastrar. Use {pessoa} para o nome de quem pediu e {comunidade} para o nome da comunidade.': 'Κάποιος γράφει την εντολή στην αρχή ενός μηνύματος, όπως !regras, και το Syden απαντά στο κανάλι με το κείμενο που θα ορίσεις. Χρησιμοποίησε το {pessoa} για το όνομα αυτού που ρώτησε και το {comunidade} για το όνομα της κοινότητας.',
