  'Modo lento: uma mensagem a cada {tempo}.': 'Αργή λειτουργία: ένα μήνυμα κάθε {tempo}.',
  'Palavras proibidas': 'Απαγορευμένες λέξεις',
  'Quanto tempo cada pessoa espera entre uma mensagem e outra no canal.': 'Πόσο περιμένει ο καθένας ανάμεσα σε δύο μηνύματα στο κανάλι.',
  'Regras': 'Κανόνες',
  'Regras que o Syden aplica sozinho, antes de a mensagem aparecer. Quem administra não passa por elas. A mensagem barrada volta para quem escreveu, com o motivo, e ninguém mais a vê.': 'Κανόνες που εφαρμόζει μόνο του το Syden, πριν εμφανιστεί το μήνυμα. Δεν ισχύουν για όσους διαχειρίζονται. Το μήνυμα που μπλοκάρεται επιστρέφει σε όποιον το έγραψε, με τον λόγο, και κανείς άλλος δεν το βλέπει.',
  'Salvo.': 'Αποθηκεύτηκε.',
  'Uma por linha. Vale a palavra inteira, sem diferença de acento ou de maiúscula: proibir uma palavra não barra outra mais longa que só a contenha.': 'Μία ανά γραμμή. Μετράει ολόκληρη η λέξη, χωρίς διαφορά τόνων ή κεφαλαίων: η απαγόρευση μιας λέξης δεν μπλοκάρει μεγαλύτερη λέξη που απλώς την περιέχει.',
  '{faltam} pontos para o nível {proximo}.': '{faltam} πόντοι μέχρι το επίπεδο {proximo}.',
  'Adicionar recompensa': 'Προσθήκη ανταμοιβής',
  'Cada mensagem vale pontos (uma por minuto), e cada minuto numa sala com mais alguém também. Quem sobe de nível recebe um aviso só para si.': 'Κάθε μήνυμα δίνει πόντους (ένα ανά λεπτό), όπως και κάθε λεπτό σε αίθουσα με κάποιον άλλο. Όποιος ανεβαίνει επίπεδο λαμβάνει ειδοποίηση μόνο για τον εαυτό του.',
  'Cargo da recompensa': 'Ρόλος ανταμοιβής',
  'Crie um cargo acima para usar como recompensa.': 'Φτιάξε έναν ρόλο παραπάνω για να τον χρησιμοποιήσεις ως ανταμοιβή.',
  'Escolha o cargo': 'Επίλεξε τον ρόλο',
