  'Você ainda não tem pontos aqui. Converse ou entre numa sala com alguém.': 'Δεν έχεις ακόμα πόντους εδώ. Συζήτησε ή μπες σε αίθουσα με κάποιον.',
  'Você chegou ao nível {nivel}!': 'Έφτασες στο επίπεδο {nivel}!',
