  'Cargos': 'Ρόλοι',
  'Cargos dão nome e cor a grupos de pessoas: "Veterano", "Turma da raide". Não mudam o que cada um pode fazer na comunidade.': 'Οι ρόλοι δίνουν όνομα και χρώμα σε ομάδες ανθρώπων: "Βετεράνοι", "Ομάδα επιδρομής". Δεν αλλάζουν τι μπορεί να κάνει ο καθένας στην κοινότητα.',
