  'Insígnias não se compram: vêm de ter feito alguma coisa. Quais delas aparecem no seu perfil, e em que ordem, você escolhe mais abaixo, em Minha conta.': 'Τα διακριτικά δεν αγοράζονται: έρχονται επειδή έκανες κάτι. Ποια εμφανίζονται στο προφίλ σου, και με ποια σειρά, το διαλέγεις πιο κάτω, στο Ο λογαριασμός μου.',
