  'Muda como os outros ouvem você na chamada. Vale na hora, dá para trocar durante a conversa — e acaba quando você sai da sala: na próxima você entra com a sua voz.': 'Αλλάζει το πώς σε ακούν οι άλλοι στην κλήση. Ισχύει αμέσως, αλλάζει και μέσα στην κουβέντα — και τελειώνει μόλις βγεις από το δωμάτιο: την επόμενη φορά μπαίνεις με τη φωνή σου.',
