  'Nada registrado ainda. Só aparecem aqui as ações com poder sobre os outros.': 'Δεν έχει καταγραφεί τίποτα ακόμη. Εδώ εμφανίζονται μόνο οι ενέργειες που έχουν εξουσία πάνω σε άλλους.',
