  'Não deu para falar com o GIPHY agora.': 'Δεν έγινε επικοινωνία με το GIPHY τώρα.',
  'Não deu para fechar o clipe agora. Tente de novo em alguns segundos.': 'Δεν έκλεισε το κλιπ τώρα. Δοκίμασε ξανά σε λίγα δευτερόλεπτα.',
