  'Nenhum GIF para essa busca.': 'Κανένα GIF για αυτή την αναζήτηση.',
  'Nenhum pacote ainda. Monte o primeiro com imagens suas, ou publique os emojis que esta comunidade já tem.': 'Κανένα πακέτο ακόμη. Φτιάξε το πρώτο με δικές σου εικόνες, ή δημοσίευσε τα emoji που έχει ήδη αυτή η κοινότητα.',
  'Nenhum som com esse nome.': 'Κανένας ήχος με αυτό το όνομα.',
  'Nenhuma denúncia até agora.': 'Καμία καταγγελία μέχρι τώρα.',
  'Nenhuma música ainda. Suba um arquivo que você tenha aí para a turma cantar.': 'Κανένα τραγούδι ακόμη. Ανέβασε ένα αρχείο που έχεις για να τραγουδήσει η παρέα.',
  'Ninguém abriu a sua transmissão ainda. O Syden só codifica a imagem quando alguém assiste — por isso não há números aqui.': 'Κανείς δεν άνοιξε ακόμη τη μετάδοσή σου. Το Syden κωδικοποιεί την εικόνα μόνο όταν κάποιος βλέπει — γι’ αυτό δεν υπάρχουν αριθμοί εδώ.',
  'Ninguém com a palavra ainda': 'Κανείς δεν έχει τον λόγο ακόμη',
  'Ninguém é avisado de que foi bloqueado.': 'Κανείς δεν ειδοποιείται ότι μπλοκαρίστηκε.',
  'Ninguém entrou em chamada este mês ainda.': 'Κανείς δεν μπήκε σε κλήση αυτόν τον μήνα ακόμη.',
  'Ninguém mais nesta comunidade ainda.': 'Κανείς άλλος σε αυτή την κοινότητα ακόμη.',
  'Ninguém na chamada — seja o primeiro': 'Κανείς στην κλήση — γίνε ο πρώτος',
  'Ninguém para sugerir por enquanto — entre numa comunidade para conhecer gente.': 'Κανείς να προτείνουμε προς το παρόν — μπες σε μια κοινότητα για να γνωρίσεις κόσμο.',
  'Ninguém respondeu neste tópico ainda.': 'Κανείς δεν απάντησε σε αυτό το νήμα ακόμη.',
