  'Dia e noite': 'Μέρα και νύχτα',
  'O avatar limpo, como sempre foi.': 'Το άβαταρ καθαρό, όπως ήταν πάντα.',
  'O canal sai da vista de todos com as mensagens dentro. Dá para trazer de volta por {dias} dias, em Configurações → Comunidade → Lixeira.': 'Το κανάλι φεύγει από τα μάτια όλων μαζί με τα μηνύματά του. Μπορεί να επανέλθει για {dias} μέρες, στις Ρυθμίσεις → Κοινότητα → Κάδος.',
  'O cartão liso.': 'Η κάρτα σκέτη.',
  'O céu inteiro girando bem devagar.': 'Όλος ο ουρανός να γυρίζει πολύ αργά.',
  'O clipe ficou grande demais para o chat. Escolha um trecho menor.': 'Το κλιπ βγήκε πολύ μεγάλο για τη συνομιλία. Διάλεξε μικρότερο κομμάτι.',
  'O navegador bloqueou as notificações deste site. Libere no cadeado ao lado do endereço e recarregue a página.': 'Ο περιηγητής μπλόκαρε τις ειδοποιήσεις αυτού του ιστότοπου. Δώσε άδεια από το λουκέτο δίπλα στη διεύθυνση και φόρτωσε ξανά τη σελίδα.',
  'o nome exato da pessoa': 'το ακριβές όνομα του ατόμου',
  'O nome muda de cor devagar.': 'Το όνομα αλλάζει χρώμα αργά.',
  'O que aconteceu?': 'Τι έγινε;',
  'O que dizer': 'Τι να πεις',
  'O que tem dentro': 'Τι έχει μέσα',
  'O que tem dentro do pacote': 'Τι έχει μέσα το πακέτο',
  'O que vamos jogar hoje?': 'Τι θα παίξουμε σήμερα;',
  'O que você fez a respeito?': 'Τι έκανες γι’ αυτό;',
  'O selo aparece aqui quando o primeiro marco cair. Até lá ele fica guardado — e chegar nele é justamente o que ele vai significar.': 'Το σήμα εμφανίζεται εδώ όταν πέσει το πρώτο ορόσημο. Μέχρι τότε μένει φυλαγμένο — και το να το φτάσεις είναι ακριβώς αυτό που θα σημαίνει.',
  'O selo desta comunidade é': 'Το σήμα αυτής της κοινότητας είναι',
  'O som chega quando você abre esta transmissão.': 'Ο ήχος έρχεται όταν ανοίξεις αυτή τη μετάδοση.',
  'O survival do Léo': 'Το survival του Λέο',
  'O Syden já sabe escrever em qualquer uma destas línguas — falta a tradução dos textos. Enquanto ela não chega, o que não estiver traduzido aparece em português, e as letras de cada alfabeto aparecem certas, sem quadradinhos.': 'Το Syden ξέρει ήδη να γράφει σε οποιαδήποτε από αυτές τις γλώσσες — λείπει η μετάφραση των κειμένων. Όσο δεν έχει έρθει, ό,τι δεν είναι μεταφρασμένο εμφανίζεται στα πορτογαλικά, και τα γράμματα κάθε αλφαβήτου φαίνονται σωστά, χωρίς τετραγωνάκια.',
  'O Syden vai ficar fora do ar por uns 10 minutos para uma atualização.': 'Το Syden θα είναι εκτός λειτουργίας για καμιά δεκαριά λεπτά για μια ενημέρωση.',
  'Observação': 'Παρατήρηση',
  'Oceania': 'Ωκεανία',
  'Oceano': 'Ωκεανός',
  'Offline': 'Εκτός σύνδεσης',
  'Olhe o seu e-mail': 'Δες το email σου',
  'Opções': 'Επιλογές',
  'Os marcos abaixo foram escolhidos para não haver como alcançá-los sozinho — todos precisam de mais de uma pessoa, ao longo do tempo.': 'Τα ορόσημα παρακάτω διαλέχτηκαν ώστε να μην μπορεί κανείς να τα φτάσει μόνος του — όλα χρειάζονται πάνω από ένα άτομο, με τον καιρό.',
  'Os outros idiomas': 'Οι άλλες γλώσσες',
  'Os outros passam a ouvir o efeito na hora. Você continua sem se escutar.': 'Οι άλλοι αρχίζουν να ακούν το εφέ αμέσως. Εσύ εξακολουθείς να μην ακούς τον εαυτό σου.',
