  'Para jogos. Manda uma imagem só, a melhor: sobra máquina para o jogo, e quem assiste recebe o que ela é.': 'Για παιχνίδια. Στέλνει μία μόνο εικόνα, την καλύτερη: μένει μηχάνημα για το παιχνίδι, και όποιος βλέπει παίρνει αυτό που είναι.',
