  'Quatro caracteres, um ícone e uma cor que aparecem ao lado do nome de quem é daqui.': 'Τέσσερις χαρακτήρες, ένα εικονίδιο και ένα χρώμα που εμφανίζονται δίπλα στο όνομα όποιου ανήκει εδώ.',
