  'Ninguém cantou ainda. Conta quando alguém põe uma música com a turma na sala.': "Κανείς δεν έχει τραγουδήσει ακόμα. Μετράει όταν κάποιος βάζει τραγούδι με την παρέα στο δωμάτιο.",
  'Idiomas': "Γλώσσες",
  'Idiomas falados': "Γλώσσες που μιλιούνται",
  'Idiomas em estudo': "Γλώσσες υπό εκμάθηση",
  'Aparece no seu cartão de perfil, para quem fala um idioma achar quem o estuda. É opcional.': "Εμφανίζεται στην κάρτα προφίλ σου, για να βρίσκει όποιος μιλά μια γλώσσα όποιον τη μαθαίνει. Είναι προαιρετικό.",
  'Feliz aniversário, {nome}!': 'Χρόνια πολλά, {nome}!',
  'Que este ano venha cheio de boas conversas, boas partidas e boa companhia.': 'Να είναι αυτή η χρονιά γεμάτη ωραίες κουβέντες, καλά παιχνίδια και καλή παρέα.',
  'Quem abre o site': 'Όποιος ανοίγει τον ιστότοπο',
  'Quem anda com você': 'Ποιος κυκλοφορεί μαζί σου',
  'Quem canta': 'Ποιος τραγουδάει',
  'quem cuida do Syden': 'όποιος φροντίζει το Syden',
  'Quem cuida do Syden vai olhar. Obrigado por avisar.': 'Όποιος φροντίζει το Syden θα το κοιτάξει. Ευχαριστούμε που το είπες.',
  'Quem está aqui não vê as suas mensagens nem você as dele, não consegue abrir conversa privada com você e não pode te mandar pedido de amizade.': 'Όποιος είναι εδώ δεν βλέπει τα μηνύματά σου ούτε εσύ τα δικά του, δεν μπορεί να ανοίξει προσωπική συνομιλία μαζί σου ούτε να σου στείλει αίτημα φιλίας.',
  'Quem estiver na sala será desconectado. Dá para trazer a sala de volta por {dias} dias, em Configurações → Comunidade → Lixeira.': 'Όποιος είναι στο δωμάτιο θα αποσυνδεθεί. Το δωμάτιο μπορεί να επανέλθει για {dias} μέρες, στις Ρυθμίσεις → Κοινότητα → Κάδος.',
  'Quem falou': 'Ποιος μίλησε',
  'Quem tiver este código entra na comunidade: pela tela de cadastro, se ainda não tem conta, ou pelo botão de entrar, se já usa o Syden.': 'Όποιος έχει αυτόν τον κωδικό μπαίνει στην κοινότητα: από την οθόνη εγγραφής, αν δεν έχει ακόμη λογαριασμό, ή από το κουμπί εισόδου, αν χρησιμοποιεί ήδη το Syden.',
  'Quente, mas sem gritar.': 'Ζεστό, αλλά χωρίς να φωνάζει.',
  'Querem falar': 'Θέλουν να μιλήσουν',
  'Rádio de avião': 'Ασύρματος αεροπλάνου',
