  'Sair de {comunidade}? As suas mensagens continuam lá para quem ficou.': 'Να φύγεις από την {comunidade}; Τα μηνύματά σου μένουν εκεί για όσους έμειναν.',
  'Sair dos outros aparelhos': 'Αποσύνδεση από τις άλλες συσκευές',
