  'Se existir uma conta com esse endereço, o link para escolher uma senha nova chegou lá. Ele vale por 1 hora.': 'Αν υπάρχει λογαριασμός με αυτή τη διεύθυνση, ο σύνδεσμος για νέο κωδικό έφτασε εκεί. Ισχύει για 1 ώρα.',
  'Selo da comunidade': 'Σήμα της κοινότητας',
