  'Sem imagem, a comunidade aparece com as iniciais do nome.': 'Χωρίς εικόνα, η κοινότητα εμφανίζεται με τα αρχικά του ονόματος.',
  'Sem moldura': 'Χωρίς πλαίσιο',
  'Senha': 'Κωδικός',
  'Senha (se tiver)': 'Κωδικός (αν υπάρχει)',
  'Senha alterada. Os outros aparelhos foram desconectados.': 'Ο κωδικός άλλαξε. Οι άλλες συσκευές αποσυνδέθηκαν.',
  'Senha atual': 'Τρέχων κωδικός',
  'Senha definida. Agora dá para entrar com nome e senha também.': 'Ο κωδικός ορίστηκε. Τώρα μπορείς να μπαίνεις και με όνομα και κωδικό.',
  'Senha trocada': 'Ο κωδικός άλλαξε',
  'Senha:': 'Κωδικός:',
  'Seria bom se…': 'Θα ήταν ωραίο αν…',
  'Seu microfone está bloqueado: ninguém está te ouvindo.': 'Το μικρόφωνό σου είναι μπλοκαρισμένο: κανείς δεν σε ακούει.',
  'Quem bloqueia é o Windows. Abra Configurações do Windows → Privacidade e segurança → Microfone e ligue o acesso para o navegador.': 'Το μπλοκάρουν τα Windows. Άνοιξε Ρυθμίσεις Windows → Απόρρητο και ασφάλεια → Μικρόφωνο και ενεργοποίησε την πρόσβαση για το πρόγραμμα περιήγησης.',
  'Clique no ícone à esquerda do endereço do site, ative o Microfone, e o Syden liga sozinho.': 'Πάτησε το εικονίδιο αριστερά από τη διεύθυνση της σελίδας, ενεργοποίησε το Μικρόφωνο, και το Syden το ανοίγει μόνο του.',
  'Seu microfone não está mandando som: ninguém está te ouvindo. Clique para escolher outro.': 'Το μικρόφωνό σου δεν στέλνει ήχο: κανείς δεν σε ακούει. Πάτησε για να διαλέξεις άλλο.',
  'Buscando…': 'Γίνεται λήψη…',
  'Buscar': 'Λήψη',
  'Link do som': 'Σύνδεσμος ήχου',
  'ou cole um link (MyInstants, por exemplo)': 'ή επικόλλησε έναν σύνδεσμο (από το MyInstants, για παράδειγμα)',
  'Ouça antes de enviar:': 'Άκου πριν το στείλεις:',
  'Não achei o áudio dessa página. No MyInstants, copie o link do botão de baixar e cole aqui.': 'Δεν βρέθηκε ήχος σε αυτή τη σελίδα. Στο MyInstants, αντίγραψε τον σύνδεσμο από το κουμπί λήψης και επικόλλησέ τον εδώ.',
  'Esse endereço não é de um arquivo de áudio.': 'Αυτή η διεύθυνση δεν είναι αρχείο ήχου.',
  'Caixa de ideias (como os outros veem)': 'Κουτί ιδεών (όπως το βλέπουν οι άλλοι)',
  'É isto que os seus amigos veem aqui embaixo do quarto. O que eles escreverem chega para você como conversa privada, com 💡 na frente — e o Syden já responde agradecendo na hora. Quando a ideia entrar no app, use o joinha na mensagem: do lado deles cai confete e a medalha aparece no perfil.': 'Αυτό βλέπουν οι φίλοι σου εδώ κάτω από το δωμάτιο. Ό,τι γράψουν σου έρχεται ως ιδιωτική συνομιλία, με 💡 μπροστά — και το Syden απαντά αμέσως με ένα ευχαριστώ. Όταν η ιδέα μπει στην εφαρμογή, βάλε έναν αντίχειρα στο μήνυμα: από τη δική τους πλευρά πέφτει κομφετί και το μετάλλιο εμφανίζεται στο προφίλ.',
  'Entre numa comunidade para ver as salas.': 'Μπες σε μια κοινότητα για να δεις τα δωμάτιά της.',
  'Escreva um pouco mais sobre a sua ideia.': 'Γράψε λίγα παραπάνω για την ιδέα σου.',
  'Esta comunidade ainda não tem sala de voz.': 'Αυτή η κοινότητα δεν έχει ακόμη δωμάτιο φωνής.',
  'vazia': 'άδειο',
  'Serve para recuperar a senha e para avisar você se algo acontecer com o Syden. Sem e-mail, uma senha esquecida não tem volta.': 'Χρησιμεύει για να ανακτάς τον κωδικό και για να σε ειδοποιούμε αν συμβεί κάτι στο Syden. Χωρίς email, ένας ξεχασμένος κωδικός δεν γυρίζει πίσω.',
  'Servidores de jogos': 'Διακομιστές παιχνιδιών',
  'Seu computador está segurando a qualidade.': 'Ο υπολογιστής σου κρατάει πίσω την ποιότητα.',
  'Seu microfone está desligado enquanto você assiste': 'Το μικρόφωνό σου είναι κλειστό όσο παρακολουθείς',
  'Seu status': 'Η κατάστασή σου',
  'Silenciar': 'Σίγαση',
  'Silenciar microfone para todos': 'Σίγαση μικροφώνου για όλους',
  'Site do Syden': 'Ιστότοπος του Syden',
  'Só o seu nome, sem selo': 'Μόνο το όνομά σου, χωρίς σήμα',
  'Só quem administra pode convidar gente nova.': 'Μόνο η διαχείριση μπορεί να προσκαλεί νέο κόσμο.',
  'Só quem administra pode instalar ou tirar.': 'Μόνο η διαχείριση μπορεί να εγκαθιστά ή να αφαιρεί.',
  'Só quem administra vê este bloco': 'Μόνο η διαχείριση βλέπει αυτό το μπλοκ',
