  'Solte para enviar o arquivo': 'Άφησέ το για να σταλεί το αρχείο',
  'Som da transmissão': 'Ήχος της μετάδοσης',
  'some em 7 dias': 'φεύγει σε 7 μέρες',
  'Some sozinho às': 'Φεύγει μόνο του στις',
  'Sons da comunidade': 'Ήχοι της κοινότητας',
  'Sons de aviso': 'Ήχοι ειδοποίησης',
  'Soundboard': 'Πίνακας ήχων',
  'Sua anotação — clique para mudar': 'Η σημείωσή σου — κάνε κλικ για αλλαγή',
  'Sua ideia': 'Η ιδέα σου',
  'Sua ideia entrou no Syden!': 'Η ιδέα σου μπήκε στο Syden!',
  'Sua ideia foi acolhida': 'Η ιδέα σου έγινε δεκτή',
  'Sua internet está segurando a qualidade.': 'Η σύνδεσή σου κρατάει πίσω την ποιότητα.',
  'Sua senha, para confirmar que é você': 'Ο κωδικός σου, για να επιβεβαιωθεί ότι είσαι εσύ',
  'Sua transmissão está sem som. O navegador só manda o som se você marcar “compartilhar áudio” na janelinha de escolher a tela.': 'Η μετάδοσή σου δεν έχει ήχο. Ο περιηγητής στέλνει ήχο μόνο αν τσεκάρεις «κοινή χρήση ήχου» στο παραθυράκι επιλογής οθόνης.',
  'Sua voz': 'Η φωνή σου',
  'Suba músicas que você já tem. Um arquivo': 'Ανέβασε τραγούδια που έχεις ήδη. Ένα αρχείο',
  'Suba só o que é seu ou o que você tem direito de usar. Ter o arquivo não é o mesmo que ter direito de tocar para outras pessoas.': 'Ανέβασε μόνο ό,τι είναι δικό σου ή ό,τι έχεις δικαίωμα να χρησιμοποιείς. Το να έχεις το αρχείο δεν είναι το ίδιο με το να έχεις δικαίωμα να το παίξεις σε άλλους.',
  'Sugestões de melhoria': 'Προτάσεις βελτίωσης',
  'Supressão de ruído': 'Καταστολή θορύβου',
  'Também dá para arrastar a borda de cada barra na tela. Dois cliques na borda volta ao padrão.': 'Μπορείς επίσης να σύρεις το περίγραμμα κάθε μπάρας στην οθόνη. Διπλό κλικ στο περίγραμμα επαναφέρει το προεπιλεγμένο.',
  'Também de graça, e também trocáveis quando quiser. Ficam nas configurações da comunidade, porque valem para a comunidade inteira e não só para você.': 'Επίσης δωρεάν, και επίσης αλλάζουν όποτε θες. Βρίσκονται στις ρυθμίσεις της κοινότητας, γιατί ισχύουν για όλη την κοινότητα και όχι μόνο για σένα.',
  'Teclas de atalho': 'Συντομεύσεις πληκτρολογίου',
