  'Título': 'Τίτλος',
  'Toca um som quando alguém entra ou sai da sua sala, quando alguém começa a compartilhar a tela e quando você silencia ou ensurdece.': 'Παίζει έναν ήχο όταν κάποιος μπαίνει ή βγαίνει από το δωμάτιό σου, όταν κάποιος αρχίζει να μοιράζεται την οθόνη και όταν βάζεις σίγαση ή κλείνεις τον ήχο.',
  'Tocando…': 'Παίζει…',
  'Todas as cores girando devagar. A mais chamativa de todas.': 'Όλα τα χρώματα να γυρίζουν αργά. Το πιο εντυπωσιακό απ’ όλα.',
  'Todo mundo desta comunidade pode usar estes emojis escrevendo {exemplo} ou pelo botão de emoji do chat. Sem assinatura: está tudo liberado.': 'Όλοι σε αυτή την κοινότητα μπορούν να χρησιμοποιούν αυτά τα emoji γράφοντας {exemplo} ή από το κουμπί emoji της συνομιλίας. Χωρίς συνδρομή: είναι όλα ανοιχτά.',
  'Tom mais alto e mais claro.': 'Πιο ψηλός και πιο καθαρός τόνος.',
  'Tom mais baixo e mais encorpado.': 'Πιο χαμηλός και πιο γεμάτος τόνος.',
  'Tráfego de saída este mês': 'Εξερχόμενη κίνηση αυτόν τον μήνα',
  'Tráfego usado da franquia': 'Κίνηση που χρησιμοποιήθηκε από το όριο',
  'Transmissões dos outros': 'Μεταδόσεις των άλλων',
  'Traz de volta os emojis que vêm com o Syden. O que vocês enviaram continua como está, e nada vira cópia repetida.': 'Επαναφέρει τα emoji που έρχονται με το Syden. Ό,τι ανεβάσατε μένει όπως είναι, και τίποτα δεν γίνεται διπλό αντίγραφο.',
