  'último dia para trazer de volta': 'τελευταία μέρα για επαναφορά',
  'Um anel claro e discreto.': 'Ένας ανοιχτόχρωμος και διακριτικός δακτύλιος.',
  'Um anel quente, cor de cobre velho.': 'Ένας ζεστός δακτύλιος, στο χρώμα του παλιού χαλκού.',
  'um canal': 'ένα κανάλι',
  'Um lugar novo, com canais próprios, e você decide quem entra.': 'Ένας καινούργιος χώρος, με δικά του κανάλια, και εσύ αποφασίζεις ποιος μπαίνει.',
  'Um lugar novo, com canais próprios. Você escolhe quem entra pelo código de convite.': 'Ένας καινούργιος χώρος, με δικά του κανάλια. Εσύ διαλέγεις ποιος μπαίνει, μέσω του κωδικού πρόσκλησης.',
  'Um pacote instalado entra para toda a comunidade: os emojis dele passam a valer nas mensagens de todo mundo.': 'Ένα πακέτο που εγκαθίσταται μπαίνει για όλη την κοινότητα: τα emoji του αρχίζουν να ισχύουν στα μηνύματα όλων.',
  'Uma imagem larga, de 1200 por 300 ou parecida. GIF animado vale, e anima de verdade. Sem capa, fica a arte que você escolheu nas boas-vindas.': 'Μια φαρδιά εικόνα, 1200 επί 300 ή κάπου εκεί. Το κινούμενο GIF μετράει, και κινείται στ’ αλήθεια. Χωρίς εξώφυλλο, μένει η εικόνα που διάλεξες στην υποδοχή.',
