  'Você ainda não tem amigos no Syden. A aba': 'Δεν έχεις ακόμη φίλους στο Syden. Η καρτέλα',
  'Você ainda não tem este item': 'Δεν έχεις ακόμη αυτό το αντικείμενο',
  'Você ainda não tem nenhuma. Elas chegam como presente ou como recompensa — por exemplo, quando uma ideia sua entra no Syden.': 'Δεν έχεις ακόμη κανένα. Έρχονται ως δώρο ή ως ανταμοιβή — για παράδειγμα, όταν μια ιδέα σου μπαίνει στο Syden.',
  'Você entrou por um serviço de fora e ainda não tem senha nesta conta. Defina uma aqui: passa a valer como segundo jeito de entrar, e é o que permite desligar aquele serviço depois.': 'Μπήκες μέσω εξωτερικής υπηρεσίας και δεν έχεις ακόμη κωδικό σε αυτόν τον λογαριασμό. Όρισε έναν εδώ: γίνεται δεύτερος τρόπος εισόδου, και είναι αυτό που σου επιτρέπει να αποσυνδέσεις αργότερα εκείνη την υπηρεσία.',
  'Você está silenciado!': 'Είσαι σε σίγαση!',
