  'Esta pessoa excluiu a conta. As mensagens daqui não chegam a ninguém.': 'Αυτό το άτομο διέγραψε τον λογαριασμό του. Τα μηνύματα από εδώ δεν φτάνουν σε κανέναν.',
  '🤖 Recado automático: sua ideia chegou, obrigado! Vou ler com calma. Se eu tiver dúvida, pergunto por aqui mesmo — e se ela entrar no Syden, você vai saber na hora.': '🤖 Αυτόματο μήνυμα: η ιδέα σου έφτασε, ευχαριστώ! Θα τη διαβάσω με την ησυχία μου. Αν έχω απορία, θα ρωτήσω εδώ ακριβώς — και αν μπει στο Syden, θα το μάθεις αμέσως.',
