  'Stop': 'Stop',
  'Sai uma letra e cada um escreve uma palavra com ela em cada categoria. Quem completar primeiro aperta STOP, e a turma decide o que vale.': 'Βγαίνει ένα γράμμα και ο καθένας γράφει σε κάθε κατηγορία μια λέξη που αρχίζει από αυτό. Όποιος τελειώσει πρώτα πατάει STOP, και η παρέα αποφασίζει τι μετράει.',
