  'Todo mundo recebe o mesmo sudoku, e a sala vê quem está mais perto de terminar.': 'Όλοι παίρνουν το ίδιο σουντόκου, και το δωμάτιο βλέπει ποιος είναι πιο κοντά στο τέλος.',
  'Cinco em linha': 'Πέντε στη σειρά',
  'Duas pessoas põem pedras no tabuleiro, uma de cada vez. Vence quem fizer cinco seguidas. A sala assiste.': 'Δύο άτομα βάζουν πέτρες στο ταμπλό, με τη σειρά. Κερδίζει όποιος κάνει πέντε στη σειρά. Το δωμάτιο παρακολουθεί.',
  'Mancala': 'Μανκάλα',
  'O jogo de semear: pegue as sementes de uma casa e espalhe uma por casa. Vence quem guardar mais no depósito. A sala assiste.': 'Το παιχνίδι της σποράς: πάρε τους σπόρους από μια θέση και ρίξε από έναν σε κάθε επόμενη. Κερδίζει όποιος μαζέψει τους περισσότερους στην αποθήκη. Το δωμάτιο παρακολουθεί.',
