  'Jogo desconhecido.': 'Άγνωστο παιχνίδι.',
  'Entre na sala de voz para jogar com a turma.': 'Μπες στο δωμάτιο φωνής για να παίξεις με την παρέα.',
  'Já tem uma partida acontecendo nesta sala.': 'Γίνεται ήδη μια παρτίδα σε αυτό το δωμάτιο.',
  'Só quem começou a partida pode encerrá-la antes do fim.': 'Μόνο όποιος ξεκίνησε την παρτίδα μπορεί να τη λήξει πριν το τέλος.',
  'Lobisomem': 'Λυκάνθρωπος',
  'À noite, escolha com os outros lobisomens quem atacar. De dia, não deixe ninguém desconfiar.': 'Τη νύχτα, διάλεξε με τους άλλους λυκανθρώπους ποιο άτομο θα δεχτεί επίθεση. Τη μέρα, μην αφήσεις κανέναν να υποψιαστεί.',
  'Vidente': 'Μάντης',
  'À noite, descubra se alguém é lobisomem. Conte de dia, se achar que vale o risco.': 'Τη νύχτα, μάθε αν κάποιο άτομο είναι λυκάνθρωπος. Πες το τη μέρα, αν πιστεύεις ότι αξίζει το ρίσκο.',
  'Anjo': 'Άγγελος',
  'À noite, escolha alguém para proteger. Se os lobisomens atacarem essa pessoa, ela sobrevive.': 'Τη νύχτα, διάλεξε ένα άτομο για να το προστατέψεις. Αν οι λυκάνθρωποι του επιτεθούν, επιζεί.',
  'Da vila': 'Του χωριού',
  'À noite, durma. De dia, descubra quem são os lobisomens e vote para tirá-los do jogo.': 'Τη νύχτα, κοιμήσου. Τη μέρα, βρες ποιοι είναι οι λυκάνθρωποι και ψήφισε για να βγουν από το παιχνίδι.',
  'A vila venceu!': 'Το χωριό νίκησε!',
  'Os lobisomens venceram!': 'Οι λυκάνθρωποι νίκησαν!',
  'Noite {n}. A vila dorme.': 'Νύχτα {n}. Το χωριό κοιμάται.',
  'Os lobisomens atacaram {nome} durante a noite.': 'Επίθεση των λυκανθρώπων μέσα στη νύχτα: {nome}.',
  'Ninguém morreu esta noite.': 'Κανείς δεν πέθανε απόψε.',
  'Dia {n}. Conversem e votem em quem vocês acham que é lobisomem.': 'Μέρα {n}. Συζητήστε και ψηφίστε το άτομο που πιστεύετε ότι είναι λυκάνθρωπος.',
  'A vila tirou {nome} do jogo.': 'Το χωριό έβγαλε από το παιχνίδι: {nome}.',
  'Empate: ninguém sai hoje.': 'Ισοπαλία: κανείς δεν βγαίνει σήμερα.',
  'Clique em quem os lobisomens vão atacar.': 'Κάνε κλικ στο άτομο που θα δεχτεί την επίθεση των λυκανθρώπων.',
  'Você já usou a sua visão esta noite.': 'Έχεις ήδη χρησιμοποιήσει το όραμά σου απόψε.',
  'Clique em alguém para descobrir se é lobisomem.': 'Κάνε κλικ σε ένα άτομο για να μάθεις αν είναι λυκάνθρωπος.',
  'Clique em quem você quer proteger esta noite.': 'Κάνε κλικ στο άτομο που θέλεις να προστατέψεις απόψε.',
  'Durma. Os outros papéis estão agindo.': 'Κοιμήσου. Οι άλλοι ρόλοι δρουν.',
  'Você saiu do jogo. Agora só assiste — sem contar nada!': 'Βγήκες από το παιχνίδι. Τώρα μόνο παρακολουθείς — χωρίς να πεις τίποτα!',
  'Clique em quem você quer tirar do jogo. O mais votado sai; empate, ninguém.': 'Κάνε κλικ στο άτομο που θέλεις να βγει από το παιχνίδι. Βγαίνει όποιο έχει τις περισσότερες ψήφους· σε ισοπαλία, κανείς.',
  'é lobisomem': 'είναι λυκάνθρωπος',
  'não é lobisomem': 'δεν είναι λυκάνθρωπος',
  'Ninguém hoje': 'Κανείς σήμερα',
  'A solução do problema.': 'Η λύση του γρίφου.',
  'Acertou! Agora é torcer pelos outros.': 'Σωστό! Τώρα εμψύχωσε τους άλλους.',
  'Esse não era o lance. Espere a solução.': 'Δεν ήταν αυτή η κίνηση. Περίμενε τη λύση.',
  'Você joga com as brancas. Ache o melhor lance.': 'Παίζεις με τα λευκά. Βρες την καλύτερη κίνηση.',
  'Você joga com as pretas. Ache o melhor lance.': 'Παίζεις με τα μαύρα. Βρες την καλύτερη κίνηση.',
  'Ver este problema no Lichess': 'Δες αυτόν τον γρίφο στο Lichess',
  'Problema do Lichess · nota {nota}': 'Γρίφος Lichess · βαθμολογία {nota}',
  'Cada um recebe um papel em segredo. À noite os lobisomens atacam; de dia a vila conversa e vota em quem tirar do jogo. Precisa de 4 pessoas ou mais.': 'Ο καθένας παίρνει κρυφά έναν ρόλο. Τη νύχτα επιτίθενται οι λυκάνθρωποι· τη μέρα το χωριό συζητά και ψηφίζει ποιος βγαίνει από το παιχνίδι. Χρειάζονται 4 άτομα ή περισσότερα.',
  'Problemas de xadrez': 'Σκακιστικοί γρίφοι',
  'Todo mundo recebe o mesmo problema do Lichess. Quem achar o lance certo mais rápido ganha o ponto extra.': 'Όλοι παίρνουν τον ίδιο γρίφο του Lichess. Όποιος βρει πιο γρήγορα τη σωστή κίνηση κερδίζει τον έξτρα πόντο.',
