  'Crie os cargos da comunidade primeiro, em Membros. Depois volte aqui para entregá-los sozinhos.': 'Φτιάξε πρώτα τους ρόλους της κοινότητας, στα Μέλη. Μετά γύρνα εδώ για να δίνονται μόνοι τους.',
