  'Toda pessoa nova recebe estes cargos ao entrar na comunidade.': 'Κάθε νέο άτομο παίρνει αυτούς τους ρόλους όταν μπαίνει στην κοινότητα.',
  'Cargos por reação': 'Ρόλοι με αντίδραση',
