  'O arquivo': 'Το αρχείο',
  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) δεν είναι πια στο Syden, γιατί {quem} δηλώνει ότι έχει τα δικαιώματα. Αν είχες άδεια δημοσίευσης, απάντησε εδώ και εξήγησε: η απάντησή σου θα ληφθεί υπόψη. Μέχρι να ξεκαθαρίσει αυτό, το περιεχόμενο μένει εκτός. Οι όροι εξηγούν πώς λειτουργεί, στην ενότητα 4: https://syden.chat/termos.html#direito-autoral',
