  'Quem precisa falar com a administração abre um ticket no início da comunidade, com um assunto. Ele vira uma conversa privada em grupo entre essa pessoa e quem administra, e aparece na lista de conversas de vocês.': 'Όποιος χρειάζεται να μιλήσει με τη διαχείριση ανοίγει ένα ticket στην αρχική της κοινότητας, με ένα θέμα. Γίνεται ιδιωτική ομαδική συνομιλία ανάμεσα σε αυτό το άτομο και τη διαχείριση, και εμφανίζεται στη λίστα συνομιλιών σας.',
