  'Não chegou em alguns minutos? Dê uma olhada no spam ou nas promoções. Se não estiver lá, mande de novo.': 'Δεν ήρθε σε λίγα λεπτά; Ρίξε μια ματιά στα ανεπιθύμητα ή στις προσφορές. Αν δεν είναι ούτε εκεί, στείλε το ξανά.',
