  'Uma comunidade é um lugar com canais de texto e salas de voz, como um servidor do Discord. Entre na de um amigo com o código de convite dele, ou crie a sua.': 'Μια κοινότητα είναι ένας χώρος με κανάλια κειμένου και δωμάτια φωνής, σαν server του Discord. Μπες στην κοινότητα ενός φίλου με τον κωδικό πρόσκλησής του ή φτιάξε τη δική σου.',
