  'nos últimos 7 dias: {tempo}': 'τις τελευταίες 7 ημέρες: {tempo}',
  'O limite combinado com o seu responsável é de {n} minutos por dia. Amanhã, o Syden abre de novo.': 'Το όριο που συμφωνήθηκε με τον κηδεμόνα σου είναι {n} λεπτά την ημέρα. Αύριο το Syden ανοίγει ξανά.',
  'O motivo (a pessoa vai ler)': 'Ο λόγος (το άτομο θα τον διαβάσει)',
  'O seu recurso foi recebido em {quando}. Quem cuida do Syden vai ler e responder.': 'Η ένστασή σου ελήφθη στις {quando}. Η ομάδα του Syden θα τη διαβάσει και θα απαντήσει.',
  'O seu responsável': 'Ο κηδεμόνας σου',
  'O seu tempo de hoje acabou': 'Ο χρόνος σου για σήμερα τελείωσε',
  'O Syden é para quem tem 13 anos ou mais.': 'Το Syden είναι για άτομα 13 ετών και άνω.',
  'O Syden é para quem tem 13 anos ou mais. Ninguém vê a sua data.': 'Το Syden είναι για άτομα 13 ετών και άνω. Κανείς δεν βλέπει την ημερομηνία σου.',
  'O Syden passou a pedir a idade de todo mundo, para proteger quem tem menos de 18 anos (a lei do ECA Digital). Ninguém vê a sua data: só a faixa de idade é usada.': 'Το Syden ζητά πλέον την ηλικία όλων, για να προστατεύει όσους είναι κάτω των 18 (ο νόμος ECA Digital). Κανείς δεν βλέπει την ημερομηνία σου: χρησιμοποιείται μόνο η ηλικιακή ομάδα.',
  'Para quem foi comunicado e o protocolo (ex.: SaferNet 123)': 'Σε ποιον αναφέρθηκε και ο αριθμός υπόθεσης (π.χ. SaferNet 123)',
  'Por segurança, a prévia das transmissões fica fechada para menores de idade.': 'Για λόγους ασφαλείας, η προεπισκόπηση των μεταδόσεων είναι κλειστή για ανηλίκους.',
  'Por segurança, menores de idade conversam no particular só com amigos.': 'Για λόγους ασφαλείας, οι ανήλικοι συνομιλούν ιδιωτικά μόνο με φίλους.',
  'Qual é a sua data de nascimento?': 'Ποια είναι η ημερομηνία γέννησής σου;',
  'Quem muda estas regras é o seu responsável.': 'Αυτούς τους κανόνες τους αλλάζει ο κηδεμόνας σου.',
  'Quem tem de 13 a 15 anos usa o Syden com a conta ligada à de um pai, mãe ou responsável. É a lei (ECA Digital), e é para a sua segurança.': 'Όσοι είναι 13 έως 15 ετών χρησιμοποιούν το Syden με τον λογαριασμό τους συνδεδεμένο με αυτόν ενός γονιού ή κηδεμόνα. Το ορίζει ο νόμος (ECA Digital) και είναι για την ασφάλειά σου.',
  'Quem tem menos de 18 anos usa o Syden com proteções a mais, e de 13 a 15 anos com a conta ligada à de um responsável (a lei do ECA Digital).': 'Όσοι είναι κάτω των 18 χρησιμοποιούν το Syden με επιπλέον προστασίες, και από 13 έως 15 ετών με τον λογαριασμό συνδεδεμένο με αυτόν ενός κηδεμόνα (ο νόμος ECA Digital).',
