  'Só um adulto pode ser o responsável por outra conta.': 'Μόνο ενήλικας μπορεί να είναι κηδεμόνας άλλου λογαριασμού.',
  'Sua conta tem uma pendência. Abra o Syden de novo para ver o que fazer.': 'Ο λογαριασμός σου έχει μια εκκρεμότητα. Άνοιξε ξανά το Syden για να δεις τι να κάνεις.',
