  'Macio e baixinho, fácil de puxar para perto da conversa.': 'Μαλακό και χαμηλό, εύκολο να το τραβήξεις κοντά στην κουβέντα.',
  'Funda e confortável, boa para ler ou ver alguém jogar.': 'Βαθιά και άνετη, καλή για διάβασμα ή για να βλέπεις κάποιον να παίζει.',
