  'Era: {nome}': 'Ήταν: {nome}',
  'Escreva o começo do nome e escolha da lista.': 'Γράψε την αρχή του ονόματος και διάλεξε από τη λίστα.',
  'Seu chute': 'Η μαντεψιά σου',
  'Chutes: {n}': 'Μαντεψιές: {n}',
  'Monstros de fantasia': 'Τέρατα φαντασίας',
  'Sai um monstro secreto, e cada um chuta outros da lista. Cada chute mostra o que bate com o secreto: tipo, tamanho, nível, alinhamento e como ele se desloca. Quem acertar com menos chutes ganha mais pontos.': 'Βγαίνει ένα μυστικό τέρας, και όλοι μαντεύουν άλλα από τη λίστα. Κάθε μαντεψιά δείχνει τι ταιριάζει με το μυστικό: τύπος, μέγεθος, επίπεδο, ευθυγράμμιση και πώς κινείται. Όποιος βρει με λιγότερες μαντεψιές παίρνει περισσότερους πόντους.',
  'Sai uma figura secreta da mitologia, e cada um chuta outras. Cada chute mostra o que bate com a secreta: a mitologia, o tipo, a forma e o que ela governa. Quem acertar com menos chutes ganha mais pontos.': 'Βγαίνει μια μυστική μορφή της μυθολογίας, και όλοι μαντεύουν άλλες. Κάθε μαντεψιά δείχνει τι ταιριάζει με τη μυστική: η μυθολογία, ο τύπος, η μορφή και τι κυβερνά. Όποιος βρει με λιγότερες μαντεψιές παίρνει περισσότερους πόντους.',
  'Países': 'Χώρες',
  'Sai um país secreto, e cada um chuta outros. Cada chute mostra a distância e a direção até o secreto, a região, a sub-região e a população. Quem acertar com menos chutes ganha mais pontos.': 'Βγαίνει μια μυστική χώρα, και όλοι μαντεύουν άλλες. Κάθε μαντεψιά δείχνει την απόσταση και την κατεύθυνση ως τη μυστική χώρα, την περιοχή, την υποπεριοχή και τον πληθυσμό. Όποιος βρει με λιγότερες μαντεψιές παίρνει περισσότερους πόντους.',
  'Apagar conversa': 'Διαγραφή συνομιλίας',
  'A conversa sai da sua lista e as mensagens somem só para você. As outras pessoas continuam vendo tudo, e uma mensagem nova traz a conversa de volta.': 'Η συνομιλία φεύγει από τη λίστα σου και τα μηνύματα χάνονται μόνο για σένα. Οι άλλοι συνεχίζουν να βλέπουν τα πάντα, και ένα νέο μήνυμα φέρνει πίσω τη συνομιλία.',
