  'Copas da Cenoura que a turma correu até o fim, na Corrida dos coelhos.': 'Κύπελλα του Καρότου που η παρέα έτρεξε ως το τέλος, στην Κούρσα κουνελιών.',
  'Bosque': 'Δάσος',
  'Cânion': 'Φαράγγι',
  'Copa do Repolho': 'Κύπελλο του Λάχανου',
  'Festa dos coelhos': 'Πάρτι των κουνελιών',
  'Cinco rodadas de jogos rápidos, cada um na própria tela: reflexo, pontaria, memória e olho. Quem for melhor em cada rodada ganha mais pontos.': 'Πέντε γύροι γρήγορων παιχνιδιών, ο καθένας στη δική του οθόνη: αντανακλαστικά, σημάδι, μνήμη και μάτι. Όποιος τα πάει καλύτερα σε κάθε γύρο παίρνει περισσότερους πόντους.',
  'Saque rápido': 'Γρήγορο τράβηγμα',
  'Espere o sinal e aperte o mais rápido que puder. Antes do sinal, está fora.': 'Περίμενε το σήμα και πάτα όσο πιο γρήγορα μπορείς. Πριν από το σήμα, είσαι εκτός.',
  'Medidor de força': 'Μετρητής δύναμης',
  'Pare a barra o mais perto possível de 100%.': 'Σταμάτα τη μπάρα όσο πιο κοντά γίνεται στο 100%.',
  'Parar o relógio': 'Σταμάτα το ρολόι',
  'Pare o relógio em 10 segundos exatos. Os números somem depois de 3.': 'Σταμάτα το ρολόι στα 10 δευτερόλεπτα ακριβώς. Οι αριθμοί εξαφανίζονται μετά το 3.',
  'Jogo dos copos': 'Το παιχνίδι με τα ποτήρια',
  'Veja onde fica a cenoura e siga o copo. Acertar mais rápido vale mais.': 'Δες πού είναι το καρότο και ακολούθησε το ποτήρι. Όσο πιο γρήγορα το βρεις, τόσο περισσότερο μετράει.',
  'Siga o coelho': 'Ακολούθησε το κουνέλι',
  'Repita as setas na ordem. A cada acerto, vem mais uma.': 'Επανέλαβε τα βέλη με τη σειρά. Με κάθε επιτυχία, έρχεται ένα ακόμα.',
  'Tiro ao alvo': 'Σκοποβολή',
  'Acerte os alvos que aparecerem. Cada um vale um ponto.': 'Χτύπα τους στόχους που εμφανίζονται. Ο καθένας αξίζει έναν πόντο.',
