  'Pulo do balanço': 'Άλμα από την κούνια',
  'Pule do balanço para cair numa folha. A mais longe vale mais.': 'Πήδα από την κούνια πάνω σε ένα φύλλο. Όσο πιο μακριά το φύλλο, τόσο περισσότερο αξίζει.',
  'Barraca de tiro': 'Σκοπευτήριο',
  'Acerte os corvos que passarem. No coelhinho, não!': 'Πέτυχε τα κοράκια που περνούν. Το κουνελάκι όχι!',
  'Brasas da fogueira': 'Κάρβουνα της φωτιάς',
  'Desvie das brasas. São só três corações!': 'Απόφυγε τα κάρβουνα. Είναι μόνο τρεις καρδιές!',
  'Cabo de guerra': 'Διελκυστίνδα',
  'Aperte a seta que aparecer para puxar a corda. Errar trava!': 'Πάτα το βέλος που εμφανίζεται για να τραβήξεις το σκοινί. Το λάθος σε κολλάει!',
  'Canteiro que encolhe': 'Το παρτέρι που μικραίνει',
  'Empurre os outros para fora do canteiro. A borda que pisca vai cair!': 'Σπρώξε τους άλλους έξω από το παρτέρι. Η άκρη που αναβοσβήνει θα πέσει!',
  'Corrida de cavalinho': 'Κούρσα με αλογάκι',
  'Alterne ← e → no ritmo. Com pressa demais, o fôlego acaba.': 'Εναλλάσσε ← και → στον ρυθμό. Με πολλή βιασύνη, σου κόβεται η ανάσα.',
  'Cartas do celeiro': 'Τα χαρτιά του αχυρώνα',
  'Na sua vez, vire uma carta ou guarde as cenouras. A raposa leva tudo!': 'Στη σειρά σου, γύρισε ένα χαρτί ή φύλαξε τα καρότα. Η αλεπού τα παίρνει όλα!',
  'Chuva de cenouras': 'Βροχή από καρότα',
  'Desça pegando as cenouras. Das pedras, fuja!': 'Κατέβαινε μαζεύοντας καρότα. Από τις πέτρες, φύγε!',
  'De galho em galho': 'Από κλαδί σε κλαδί',
  'Solte o cipó quando ele estiver na faixa clara.': 'Άφησε την περικοκλάδα όταν είναι στη φωτεινή λωρίδα.',
  'Colheita em dupla': 'Συγκομιδή στα δύο',
  'Em dupla: quem está no galho solta os morangos maduros, e quem está embaixo apanha com a cesta.': 'Στα δύο: όποιος είναι στο κλαδί ρίχνει τις ώριμες φράουλες, κι όποιος είναι κάτω τις πιάνει με το καλάθι.',
  'Baile da toca': 'Χορός στο λαγούμι',
  'Guarde a ordem da dança. No fim, diga quem dançou na lâmpada marcada.': 'Θυμήσου τη σειρά του χορού. Στο τέλος πες ποιος χόρεψε στη σημαδεμένη λάμπα.',
  'Chão que desmorona': 'Το πάτωμα που καταρρέει',
  'A tábua racha quando alguém para em cima. Continue andando e empurre os outros para a água!': 'Η σανίδα ραγίζει όταν κάποιος σταματά πάνω της. Συνέχισε να περπατάς και σπρώξε τους άλλους στο νερό!',
  'Arrume a despensa': 'Τακτοποίησε το κελάρι',
  'Guarde onde fica cada pote e ponha todos de volta no lugar.': 'Θυμήσου πού είναι κάθε βάζο και βάλ\' τα όλα πίσω στη θέση τους.',
  'Esconde-esconde na horta': 'Κρυφτό στον λαχανόκηπο',
  'Esconda-se onde a lanterna não vai olhar. Quem tem a lanterna procura!': 'Κρύψου εκεί που δεν θα κοιτάξει ο φακός. Όποιος έχει τον φακό ψάχνει!',
  'Três flechas': 'Τρία βέλη',
  'A flecha sobe reta e fura o que encontrar. Os balões pequenos valem mais.': 'Το βέλος ανεβαίνει ίσια και τρυπά ό,τι βρει. Τα μικρά μπαλόνια αξίζουν περισσότερο.',
  'Bate quando der a flor': 'Χτύπα στο λουλούδι',
  'Bata quando aparecer a flor igual à do quadrinho. Na figura errada, está fora.': 'Χτύπα όταν εμφανιστεί το ίδιο λουλούδι με αυτό στο πλαίσιο. Σε λάθος εικόνα, βγαίνεις εκτός.',
  'Foguete de cenoura': 'Πύραυλος-καρότο',
  'Bombeie quando o anel acender. Fora do ritmo, o ar escapa.': 'Φούσκωνε όταν ανάβει το δαχτυλίδι. Εκτός ρυθμού, ο αέρας φεύγει.',
  'Pegue a galinha': 'Πιάσε την κότα',
  'Encurrale a galinha. Cansada, ela fica lenta.': 'Στρίμωξε την κότα σε μια γωνία. Κουρασμένη, γίνεται αργή.',
  'Repolhos no gelo': 'Λάχανα στον πάγο',
  'Pegue as cenouras no gelo e fuja dos repolhos.': 'Μάζεψε τα καρότα στον πάγο και ξέφυγε από τα λάχανα.',
  'Abóboras ladeira abaixo': 'Κολοκύθες στην κατηφόρα',
  'Lá de cima rolam abóboras; quem sobe troca de faixa para fugir delas!': 'Από πάνω κυλούν κολοκύθες· όποιος ανεβαίνει αλλάζει λωρίδα για να τις αποφύγει!',
  'Quem está atrás da turma?': 'Ποιος είναι πίσω από το πλήθος;',
  'Descubra quem está escondido. Uma chance só: quanto antes, mais vale.': 'Βρες ποιος κρύβεται. Μία μόνο ευκαιρία: όσο νωρίτερα, τόσο περισσότερο αξίζει.',
  'Arremesso do nabo': 'Ρίψη γογγυλιού',
  'Solte quando o nabo apontar para o campo. Girando mais rápido, vai mais longe.': 'Άφησε όταν το γογγύλι δείχνει προς το γήπεδο. Όσο πιο γρήγορα γυρίζει, τόσο πιο μακριά πάει.',
  'Onda no açude': 'Κύμα στη λιμνούλα',
  'Quem está no remo manda ondas; quem está na jangada pula na hora!': 'Όποιος είναι στο κουπί στέλνει κύματα· όποιος είναι στη σχεδία πηδά στην ώρα του!',
  'Pula o ponteiro': 'Πήδα τον δείκτη',
  'Pule quando o ponteiro passar. Ele fica cada vez mais rápido.': 'Πήδα όταν περνά ο δείκτης. Γίνεται όλο και πιο γρήγορος.',
  'Ponte do riacho': 'Η γέφυρα του ρυακιού',
  'Leve as três tábuas até a ponte. Cuidado com as pedras que afundam!': 'Πήγαινε τις τρεις σανίδες ως τη γέφυρα. Προσοχή στις πέτρες που βουλιάζουν!',
  'Quem está em qual toca?': 'Ποιος είναι σε ποιο λαγούμι;',
  'Siga os bichos de toca em toca. No fim, aponte onde está o do balão.': 'Ακολούθησε τα ζωάκια από λαγούμι σε λαγούμι. Στο τέλος δείξε πού είναι αυτό στο συννεφάκι.',
  'As chaves da porteira': 'Τα κλειδιά της αυλόπορτας',
  'Pegue uma cenoura dourada e leve até a porteira. Falta uma: empurre quem estiver carregando!': 'Πάρε ένα χρυσό καρότο και πήγαινέ το στην αυλόπορτα. Λείπει ένα: σπρώξε όποιον το κουβαλά!',
  'Destampe os potes': 'Άνοιξε τα βάζα',
  'Gire cada tampa para o lado da seta, depressa. O lado errado aperta de novo.': 'Γύρνα κάθε καπάκι προς τη μεριά του βέλους, γρήγορα. Η λάθος μεριά το σφίγγει ξανά.',
  'Praga na toca': 'Παράσιτα στο λαγούμι',
  'Bata nas lagartas que saírem das tocas. No coelhinho, não!': 'Χτύπα τις κάμπιες που βγαίνουν από τα λαγούμια. Το κουνελάκι όχι!',
  'Rebater o rabanete': 'Χτύπα το ραπανάκι',
  'Rebata quando o rabanete chegar à base. Bem na hora, vai mais longe.': 'Χτύπα όταν το ραπανάκι φτάσει στη βάση. Ακριβώς στην ώρα, πάει πιο μακριά.',
  'Regar a horta': 'Πότισε τον λαχανόκηπο',
