  'Uma banana': 'Με μπανάνα',
  'Uma cenoura': 'Με καρότο',
  'Qual destes é uma fruta vermelha?': 'Ποιο από αυτά είναι κόκκινο φρούτο;',
  'Batata': 'Πατάτα',
  'Que bicho é o mascote do Syden?': 'Τι ζώο είναι η μασκότ του Syden;',
