  'O coelho do recado': 'Το κουνέλι του μηνύματος',
  'Ninguém': 'Κανείς',
  'O que a estante de troféus do quarto mostra?': 'Τι δείχνει το ράφι με τα τρόπαια στο δωμάτιο;',
