  'Voar': 'Πτήση',
  'Desvie das sementes e derrube a praga. O espantalho vem no fim.': 'Απόφυγε τους σπόρους και ρίξε τα παράσιτα. Το σκιάχτρο έρχεται στο τέλος.',
  'Sem vidas: agora é torcer pela esquadrilha.': 'Τέλος οι ζωές: τώρα εμψύχωσε τη μοίρα.',
