  'Gêneros': 'Είδη',
  'Tocas e Torres': 'Λαγούμια και Πύργοι',
  'Estratégia em tempo real contra o computador: colete comida, madeira e ouro, construa a vila, avance de era e treine o exército. Ganha quem derrubar o centro da vila do outro, ou construir a Maravilha e mantê-la de pé por 2 minutos.': 'Στρατηγική πραγματικού χρόνου κατά του υπολογιστή: μάζεψε τροφή, ξύλο και χρυσό, χτίσε το χωριό, πέρνα στην επόμενη εποχή και εκπαίδευσε τον στρατό. Κερδίζει όποιος γκρεμίσει το κέντρο του χωριού του άλλου ή χτίσει το Θαύμα και το κρατήσει όρθιο για 2 λεπτά.',
