  'Mover o mapa': 'Μετακίνηση χάρτη',
  'Este jogo não se joga na sala.': 'Αυτό το παιχνίδι δεν παίζεται στο δωμάτιο.',
  'Ponha os seus navios no mar.': 'Βάλε τα πλοία σου στη θάλασσα.',
  'Esperando {nome} pôr os navios…': 'Αναμονή για να βάλει {nome} τα πλοία…',
  'Os dois estão pondo os navios…': 'Και οι δύο βάζουν τα πλοία τους…',
  'Navio de {n} casas': 'Πλοίο {n} τετραγώνων',
  'Seus navios': 'Τα πλοία σου',
  'Escolha um navio e toque no mar. Arraste para mudar de lugar.': 'Διάλεξε ένα πλοίο και άγγιξε τη θάλασσα. Σύρε για να το μετακινήσεις.',
  'Sortear a frota': 'Τυχαίος στόλος',
  'Sua frota já está pronta.': 'Ο στόλος σου είναι ήδη έτοιμος.',
  'Ponha todos os navios antes.': 'Βάλε πρώτα όλα τα πλοία.',
  'Escolha um navio.': 'Διάλεξε ένα πλοίο.',
  'O navio não cabe aí.': 'Το πλοίο δεν χωράει εκεί.',
  'Os navios não podem encostar um no outro.': 'Τα πλοία δεν μπορούν να ακουμπούν το ένα το άλλο.',
  'Minigolfe 3D': 'Μίνι γκολφ 3D',
  'Oito buracos em 3D, com rampas, castelo e moinho, todos jogando o mesmo ao mesmo tempo. Arraste para mirar e dar a força, e solte. Ganha quem somar menos tacadas.': 'Οκτώ τρύπες σε 3D, με ράμπες, κάστρο και ανεμόμυλο, όλοι παίζουν την ίδια την ίδια στιγμή. Σύρε για να σημαδέψεις και να δώσεις δύναμη, και άφησε. Κερδίζει όποιος μαζέψει τα λιγότερα χτυπήματα.',
  'Ver o buraco de cima': 'Δες την τρύπα από ψηλά',
  'Fora da pista! Mais uma tacada.': 'Εκτός διαδρομής! Ένα χτύπημα παραπάνω.',
  'Arraste para o lado para mirar e para baixo para a força, e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Σύρε στο πλάι για να σημαδέψεις και προς τα κάτω για δύναμη, και άφησε. Στο πληκτρολόγιο: τα βέλη σημαδεύουν, και το Διάστημα πατημένο δίνει τη δύναμη.',
  'Futebol dos coelhos': 'Ποδόσφαιρο των κουνελιών',
  'Futebol de campo pequeno, visto de cima. Encoste na bola para conduzir, segure Espaço para chutar mais forte e passe com X. Na sala, os times se completam com robôs.': 'Ποδόσφαιρο σε μικρό γήπεδο, από ψηλά. Άγγιξε την μπάλα για να την οδηγήσεις, κράτα το Διάστημα για πιο δυνατό σουτ και πάσαρε με το X. Στο δωμάτιο, οι ομάδες συμπληρώνονται με ρομπότ.',
  'Quantos por time?': 'Πόσοι ανά ομάδα;',
  'Seu time venceu!': 'Η ομάδα σου κέρδισε!',
  'Seu time perdeu.': 'Η ομάδα σου έχασε.',
  'Passe': 'Πάσα',
  'Chutar': 'Σουτ',
  'Chutar (segure para mais força)': 'Σουτ (κράτα για περισσότερη δύναμη)',
  'Gol!': 'Γκολ!',
  'Gol contra': 'Αυτογκόλ',
  'Partida inválida.': 'Μη έγκυρη παρτίδα.',
  'Ninguém para jogar.': 'Δεν υπάρχει κανείς για να παίξει.',
  'Caça às pragas da horta': 'Κυνήγι παρασίτων στον λαχανόκηπο',
  'Corvos e gafanhotos atacam a horta. Mire e clique para acertar antes que fujam: a munição é contada, e cada onda vem mais rápida. Ganha quem fizer mais pontos.': 'Κοράκια και ακρίδες επιτίθενται στον λαχανόκηπο. Σημάδεψε και κάνε κλικ για να τα πετύχεις πριν φύγουν: τα πυρομαχικά είναι μετρημένα, και κάθε κύμα έρχεται πιο γρήγορα. Κερδίζει όποιος μαζέψει τους περισσότερους πόντους.',
  'Mire e clique nas pragas antes que fujam. Cada tiro gasta uma cenoura.': 'Σημάδεψε και κάνε κλικ στα παράσιτα πριν φύγουν. Κάθε βολή ξοδεύει ένα καρότο.',
  'Munição: {n}': 'Πυρομαχικά: {n}',
  'Pontos: {n}': 'Πόντοι: {n}',
  'Nesta onda': 'Σε αυτό το κύμα',
  'Acabou a munição desta onda.': 'Τα πυρομαχικά αυτού του κύματος τελείωσαν.',
