  'Setas para mover, Espaço para trocar, X para subir a pilha.': 'Βέλη για κίνηση, Διάστημα για ανταλλαγή, X για να ανεβάσεις τη στοίβα.',
  'A horta está salva!': 'Ο κήπος σώθηκε!',
