  'Total': 'Σύνολο',
  'Tacadas: {n}': 'Χτυπήματα: {n}',
  'Puxe a bola para trás e solte. No teclado: as setas miram, e o Espaço segurado dá a força.': 'Τράβηξε την μπάλα πίσω και άφησέ την. Στο πληκτρολόγιο: τα βέλη σημαδεύουν, και το Διάστημα πατημένο δίνει τη δύναμη.',
  'Na água! Mais uma tacada.': 'Στο νερό! Ένα χτύπημα παραπάνω.',
