  'Acabaram as tacadas.': 'Τελείωσαν τα χτυπήματα.',
  'Para a esquerda': 'Αριστερά',
  'Para a direita': 'Δεξιά',
  'Setas para correr, Espaço para pular (segure para ir mais alto).': 'Βέλη για τρέξιμο, Διάστημα για άλμα (κράτα το για πιο ψηλά).',
  'Nenhum amigo jogou esta fase ainda.': 'Κανένας φίλος δεν έχει παίξει ακόμα αυτή την πίστα.',
  'Chuva na horta: todo mundo ganha {n} cenouras.': 'Βροχή στον κήπο: όλοι παίρνουν {n} καρότα.',
  '{nome} achou {n} cenouras escondidas.': '{nome} βρήκε {n} κρυμμένα καρότα.',
  '{nome} trocou de lugar com {outro}.': '{nome} άλλαξε θέση με {outro}.',
  'Faltou gente: a partida acabou antes do fim, sem troféus.': 'Έλειψε κόσμος: η παρτίδα τελείωσε πριν την ώρα της, χωρίς τρόπαια.',
  'Saiu antes do fim': 'Έφυγε πριν το τέλος',
  'Jogar o dado': 'Ρίξε το ζάρι',
  '{nome} comprou a cenoura dourada!': '{nome} αγόρασε το χρυσό καρότο!',
  'Comprar a cenoura dourada por {preco} cenouras?': 'Αγορά του χρυσού καρότου για {preco} καρότα;',
  'Comprar': 'Αγορά',
  '{nome} chegou à cenoura dourada.': '{nome} έφτασε στο χρυσό καρότο.',
  'Quantas rodadas?': 'Πόσοι γύροι;',
  'Os coelhos defendem a horta de raposas, corvos e um texugo. Andem juntos, batam em combo e cuidem uns dos outros: de 1 a 4 pessoas.': 'Τα κουνέλια υπερασπίζονται τον κήπο από αλεπούδες, κοράκια κι έναν ασβό. Προχωρήστε μαζί, χτυπήστε με κόμπο και προσέχετε ο ένας τον άλλον: από 1 έως 4 άτομα.',
  'Pulo do coelho': 'Άλμα του κουνελιού',
  'Uma corrida de plataforma: correr, pular e não cair. Sozinho, contra o relógio e os fantasmas dos amigos; com a turma, ao vivo, numa fase ou nas três.': 'Αγώνας πλατφόρμας: τρέξε, πήδα και μην πέσεις. Ατομικά, με το χρονόμετρο και τα φαντάσματα των φίλων σου· με την παρέα, ζωντανά, σε μία πίστα ή και στις τρεις.',
  'Troque dois legumes vizinhos para juntar três ou mais iguais. A pilha sobe sem parar: não deixe chegar ao topo. Com a turma, as cadeias e os combos mandam caixotes para os outros.': 'Άλλαξε θέση σε δύο γειτονικά λαχανικά για να ενώσεις τρία ή περισσότερα ίδια. Η στοίβα ανεβαίνει ασταμάτητα: μην την αφήσεις να φτάσει στην κορυφή. Με την παρέα, οι αλυσίδες και τα κόμπο στέλνουν κιβώτια στους άλλους.',
  'Seis buracos de minigolfe, todos jogando o mesmo ao mesmo tempo. Puxe a bola para trás e solte para dar a tacada. Ganha quem somar menos tacadas.': 'Έξι τρύπες μίνι γκολφ, όλοι παίζουν την ίδια ταυτόχρονα. Τράβηξε την μπάλα πίσω και άφησέ την για να χτυπήσεις. Κερδίζει όποιος μαζέψει τα λιγότερα χτυπήματα.',
  'Cada um joga o dado na sua vez e anda pela horta. Junte cenouras para comprar a cenoura dourada, e depois de cada rodada a turma joga um microjogo. Ganha quem tiver mais cenouras douradas.': 'Στη σειρά σου ρίχνεις το ζάρι και προχωράς στον κήπο. Μάζεψε καρότα για να αγοράσεις το χρυσό καρότο, και μετά από κάθε γύρο η παρέα παίζει ένα μικροπαιχνίδι. Κερδίζει όποιος έχει τα περισσότερα χρυσά καρότα.',
  'Os pódios e as conquistas da turma': 'Τα βάθρα και τα επιτεύγματα της παρέας',
