  'Ande pelas capitais do Brasil, compre cidades e cobre aluguel de quem parar nelas. Com uma região inteira, dá para construir prédios. Troque, dispute nos leilões e não fique sem dinheiro.': 'Γύρνα τις πρωτεύουσες της Βραζιλίας, αγόρασε πόλεις και μάζεψε ενοίκιο από όποιον σταματά σε αυτές. Με μια ολόκληρη περιοχή μπορείς να χτίσεις κτίρια. Κάνε ανταλλαγές, διεκδίκησε στις δημοπρασίες και μη μείνεις χωρίς λεφτά.',
