  'Batalha naval': 'Ναυμαχία',
  'O dominó de sempre, de 2 a 4 pessoas (com 4, em duplas). Encaixe as pedras pelas pontas, e quem bater primeiro leva os pontos das mãos dos outros.': 'Το κλασικό ντόμινο, για 2 έως 4 άτομα (με 4, σε ζευγάρια). Ταίριαξε τα πλακίδια στις άκρες, και όποιος τελειώσει πρώτος παίρνει τους πόντους από τα χέρια των άλλων.',
  'O truco paulista, com vira e manilha, em 2 ou em duplas de 4. Peça truco, aumente para seis, nove e doze, ou corra. Ganha quem fizer 12 pontos.': 'Το βραζιλιάνικο τρούκο, με το γυρισμένο φύλλο και τα ατού, για 2 ή σε ζευγάρια των 4. Ζήτα τρούκο, ανέβασε σε έξι, εννιά και δώδεκα, ή φύγε. Κερδίζει όποιος φτάσει τους 12 πόντους.',
  'As damas brasileiras: comer é obrigatório, para a frente e para trás, e a dama anda a diagonal inteira. A sala assiste.': 'Η βραζιλιάνικη ντάμα: το φάγωμα είναι υποχρεωτικό, μπρος και πίσω, και η ντάμα κινείται σε όλη τη διαγώνιο. Η αίθουσα παρακολουθεί.',
  'Cada um esconde a sua frota e atira no mar do outro. Acertou, atira de novo. Vence quem afundar a frota inteira primeiro. A sala assiste.': 'Ο καθένας κρύβει τον στόλο του και ρίχνει στη θάλασσα του άλλου. Αν πετύχεις, ρίχνεις ξανά. Κερδίζει όποιος βυθίσει πρώτος ολόκληρο τον στόλο. Η αίθουσα παρακολουθεί.',
