  'Pegue os ingredientes nos caixotes, pique na tábua, cozinhe no fogão e no forno sem queimar, monte no prato e entregue na janela. Todos recebem os mesmos pedidos: ganha quem entregar mais pratos em 3 minutos.': "Πάρε τα υλικά από τα κιβώτια, κόψ' τα στο ξύλο, μαγείρεψέ τα στη φωτιά και στον φούρνο χωρίς να καούν, στήσε το πιάτο και παράδωσέ το στο παράθυρο. Όλοι παίρνουν τις ίδιες παραγγελίες: κερδίζει όποιος παραδώσει τα περισσότερα πιάτα σε 3 λεπτά.",
